{
  "name": "my-package",
  "version": "1.0.0",
  "description": "A minimal Node.js package exporting a simple greet function",
  "main": "index.js",
  "files": [
    "index.js"
  ],
  "scripts": {
    "build": "mkdir -p dist && npm pack --pack-destination dist",
    "sbom": "npx --yes @cyclonedx/cyclonedx-npm@6.0.1 --package-lock-only --spec-version 1.6 --output-reproducible --output-file sbom.cdx.json && node scripts/enrich-sbom.js sbom.cdx.json",
    "release": "npm run build && npm run sbom && node scripts/make-release.js"
  },
  "dependencies": {
    "ms": "2.1.3"
  },
  "keywords": [],
  "license": "MIT"
}
